/**
 * Guard middleware.
 *
 * @template E - The environment type.
 * @param {GuardOptions} options - The options.
 * @returns {Middleware<E>} The middleware.
 */
export const guard = (options) => {
  return async function guard(ctx, next) {
    if (ctx.token !== options.token) {
      ctx.log.push(`denied ${ctx.path}`);
      return;
    }
    ctx.log.push(`allowed ${ctx.path}`);
    await next();
  };
};

export class Router {
  constructor() {
    this.routes = [];
  }

  on(path, ...handlers) {
    this.routes.push({ path, handlers });
    return this;
  }

  async dispatch(path, token) {
    const log = [];
    for (const route of this.routes) {
      if (route.path !== path) continue;
      const ctx = { path, token, log };
      let index = 0;
      const next = async () => {
        const handler = route.handlers[index++];
        if (handler) await handler(ctx, next);
      };
      await next();
    }
    return log;
  }
}
